const transcript = $input.first().json.body.transcript;

if (!transcript || typeof transcript !== 'string' || transcript.trim().length === 0) {
  throw new Error('No transcript text provided');
}

if (transcript.length > 50000) {
  throw new Error('Transcript too long. Max 50,000 characters.');
}

return {
  json: {
    transcript: transcript.trim(),
    charCount: transcript.length
  }
};

const transcript = $input.first().json.transcript;

const systemPrompt = `You are an expert conversation analyst specializing in call center and customer service transcripts. Analyze the given conversation transcript and return ONLY valid JSON (no markdown fences, no preamble, no explanation outside the JSON structure) matching this exact schema:

{
  "overall_sentiment": "Positive" | "Negative" | "Neutral",
  "overall_confidence": <number 0-100>,
  "overall_reasoning": "<2-3 sentence explanation of WHY this overall sentiment was chosen, citing specific patterns from the conversation>",
  "sentiment_breakdown": {
    "positive_pct": <number 0-100>,
    "negative_pct": <number 0-100>,
    "neutral_pct": <number 0-100>
  },
  "sentence_level": [
    {
      "sentence": "<exact sentence from transcript>",
      "speaker": "<speaker label if identifiable, else 'Unknown'>",
      "sentiment": "Positive" | "Negative" | "Neutral",
      "emotion": "<one of: joy, frustration, anger, sadness, satisfaction, confusion, anxiety, gratitude, neutral>",
      "intensity": <number 0-100, how strongly the emotion is expressed>,
      "reason": "<3-8 word phrase naming the specific word or pattern that drove this sentiment call, e.g. 'word choice: really frustrated' or 'expresses relief after fix'>"
    }
  ],
  "emotion_distribution": {
    "joy": <count>,
    "frustration": <count>,
    "anger": <count>,
    "sadness": <count>,
    "satisfaction": <count>,
    "confusion": <count>,
    "anxiety": <count>,
    "gratitude": <count>,
    "neutral": <count>
  },
  "conversation_summary": "<3-5 sentence neutral summary of what happened in the conversation, the customer's issue, and the resolution status>",
  "kpis": {
    "customer_satisfaction_score": <number 0-100, estimated CSAT based on tone trajectory>,
    "resolution_status": "Resolved" | "Unresolved" | "Escalated" | "Partially Resolved",
    "agent_empathy_score": <number 0-100, how empathetic/professional the agent sounded>,
    "sentiment_trend": "Improving" | "Declining" | "Stable" | "Volatile",
    "escalation_risk": "Low" | "Medium" | "High",
    "escalation_risk_reasoning": "<1 sentence why>",
    "key_issues_mentioned": ["<short issue label>", "..."],
    "action_items": ["<follow-up action implied by the conversation>", "..."],
    "talk_time_balance": "<rough estimate, e.g. 'Agent-dominant', 'Customer-dominant', 'Balanced', based on text volume per speaker if speakers are identifiable, else 'Not determinable'"
  }
}

Rules:
- Break the transcript into individual sentences for sentence_level analysis. If the transcript is very long (60+ sentences), sample representative sentences evenly across the conversation rather than every single one, but note this is not required to actually trim it if it's reasonable.
- Use your best judgment to identify speakers (e.g. 'Agent:', 'Customer:', names) if present in the text. If no speaker labels exist, use 'Unknown'.
- Be analytically honest. Do not default to Neutral/Positive just to be safe. If the conversation shows real frustration or anger, say so.
- overall_reasoning must reference actual content/patterns from the transcript, not generic statements.
- Return ONLY the JSON object. No markdown code fences, no extra text.`;

const userPrompt = `Analyze this conversation transcript:\n\n${transcript}`;

return {
  json: {
    systemPrompt,
    userPrompt,
    transcript
  }
};

