const response = $input.first().json;

let rawText;
try {
  if (response.candidates) {
    // Gemini shape
    rawText = response.candidates[0].content.parts[0].text;
  } else if (response.choices) {
    // Groq (OpenAI-compatible) shape
    rawText = response.choices[0].message.content;
  } else {
    throw new Error('Unrecognized response shape');
  }
} catch (e) {
  throw new Error('Unexpected AI response shape: ' + JSON.stringify(response).slice(0, 500));
}

let parsed;
try {
  const cleaned = rawText.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON output: ' + e.message);
}

// Basic shape validation with safe fallbacks so the frontend never breaks
parsed.overall_sentiment = parsed.overall_sentiment || 'Neutral';
parsed.sentence_level = Array.isArray(parsed.sentence_level) ? parsed.sentence_level : [];
parsed.emotion_distribution = parsed.emotion_distribution || {};
parsed.kpis = parsed.kpis || {};
parsed.conversation_summary = parsed.conversation_summary || 'No summary available.';

return {
  json: {
    success: true,
    analyzedAt: new Date().toISOString(),
    ...parsed
  }
};
